    private static List<(string PakPrefix, string RelPath, byte[] TemplateData)>? _cachedTemplates;

    /// <summary>
    /// 取得所有額外戰役與劇本的 XML 模板條目清單。
    /// 回傳項目包含：(PakPrefix, RelPath, TemplateData)
    /// 例如：("ADVENTURES\\RETURN TO THE THRONE", "ADVENTURE.LOC.XML", byte[])
    /// </summary>
    public static IReadOnlyList<(string PakPrefix, string RelPath, byte[] TemplateData)> GetTemplates()
    {
        if (_cachedTemplates != null)
        {
            return _cachedTemplates;
        }

        byte[] compBytes = Convert.FromBase64String(CompressedBase64);
        using var msIn = new MemoryStream(compBytes);
        using var gz = new GZipStream(msIn, CompressionMode.Decompress);
        using var msOut = new MemoryStream();
        gz.CopyTo(msOut);
        byte[] decompressed = msOut.ToArray();

        var dict = JsonSerializer.Deserialize<Dictionary<string, Dictionary<string, string>>>(decompressed);
        var result = new List<(string, string, byte[])>();

        if (dict != null)
        {
            foreach (var (pakPrefix, files) in dict)
            {
                foreach (var (relPath, xmlText) in files)
                {
                    string cleanXml = CleanMojibake(xmlText);
                    byte[] data = Encoding.UTF8.GetBytes(cleanXml);
                    result.Add((pakPrefix, relPath, data));
                }
            }
        }

        _cachedTemplates = result;
        return _cachedTemplates;
    }

    /// <summary>
    /// 清除歷史提取時因以 Latin-1/Windows-1252 解碼 UTF-8 位元組所殘留之 Mojibake 引號與標點符號。
    /// </summary>
    public static string CleanMojibake(string s)
    {
        if (string.IsNullOrEmpty(s)) return s;
        return s
            .Replace("â\u0080\u0099", "’")
            .Replace("â\u0080\u0098", "‘")
            .Replace("â\u0080¦", "…")
            .Replace("â\u0080\u0093", "–")
            .Replace("â\u0080\u0094", "—")
            .Replace("â\u0080\u009c", "“")
            .Replace("â\u0080\u009d", "”")
            .Replace("Ã¢â\u0082¬â\u0084¢", "’");
    }
}
